"use client";

import { useState, useRef, useCallback } from "react";
import { Scan, MenuItem } from "@/types/menu";

type ScanStatus = "idle" | "uploading" | "processing" | "completed" | "error";

interface ScanState {
  status: ScanStatus;
  progress: number;
  scan: Scan | null;
  items: MenuItem[];
  error: string | null;
  currentDish: string | null;
  dishProgress: { done: number; total: number } | null;
}

interface ScanResult {
  scan: Scan;
  items: MenuItem[];
  agent_summary?: string | null;
  enriched?: boolean;
}

export function useScan() {
  const [state, setState] = useState<ScanState>({
    status: "idle",
    progress: 0,
    scan: null,
    items: [],
    error: null,
    currentDish: null,
    dishProgress: null,
  });

  const abortRef = useRef<AbortController | null>(null);

  const startScan = useCallback(async (file: File): Promise<ScanResult | void> => {
    if (abortRef.current) {
      abortRef.current.abort();
    }
    const controller = new AbortController();
    abortRef.current = controller;

    setState({
      status: "uploading",
      progress: 10,
      scan: null,
      items: [],
      error: null,
      currentDish: null,
      dishProgress: null,
    });

    try {
      const formData = new FormData();
      formData.append("image", file, file.name || "menu.jpg");

      const response = await fetch("/api/scan/new", {
        method: "POST",
        body: formData,
        signal: controller.signal,
      });

      if (!response.ok) {
        const text = await response.text();
        let errorMessage = `Scan failed with status ${response.status}`;
        try {
          const data = JSON.parse(text);
          if (data.message) errorMessage = data.message;
        } catch {
          // ignore parse error
        }
        throw new Error(errorMessage);
      }

      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error("No response stream");
      }

      const decoder = new TextDecoder();
      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || "";

        let currentEvent = "status";

        for (const line of lines) {
          if (line.startsWith("event: ")) {
            currentEvent = line.slice(6).trim();
            continue;
          }
          if (line.startsWith("data: ")) {
            const dataStr = line.slice(6).trim();
            if (!dataStr) continue;

            let data: {
              status?: string;
              message?: string;
              error?: string;
              progress?: number;
              scan?: Scan;
              items?: MenuItem[];
              agent_summary?: string | null;
              enriched?: boolean;
              dish?: string;
              done?: number;
              total?: number;
            };
            try {
              data = JSON.parse(dataStr);
            } catch {
              continue;
            }

            if (currentEvent === "error") {
              const errMsg = data.message || data.error || "Something went wrong";
              setState({
                status: "error",
                progress: 0,
                scan: null,
                items: [],
                error: errMsg,
                currentDish: null,
                dishProgress: null,
              });
              throw new Error(errMsg);
            }

            if (currentEvent === "dish_progress") {
              setState((prev) => ({
                ...prev,
                status: "processing",
                currentDish: data.dish || prev.currentDish,
                dishProgress: {
                  done: data.done ?? prev.dishProgress?.done ?? 0,
                  total: data.total ?? prev.dishProgress?.total ?? 1,
                },
                progress: data.progress ?? prev.progress,
              }));
              continue;
            }

            if (data.status === "complete" && data.scan && data.items) {
              setState({
                status: "completed",
                progress: 100,
                scan: data.scan,
                items: data.items,
                error: null,
                currentDish: null,
                dishProgress: null,
              });
              return {
                scan: data.scan,
                items: data.items,
                agent_summary: data.agent_summary,
                enriched: data.enriched,
              };
            }

            if (data.status) {
              setState((prev) => ({
                ...prev,
                status: (data.status === "researching" ? "processing" : data.status) as ScanStatus,
                progress: data.progress ?? prev.progress,
              }));
            }
          }
        }
      }

      throw new Error("Stream ended unexpectedly");
    } catch (error: unknown) {
      if ((error as Error).name === "AbortError") {
        return;
      }
      const message = error instanceof Error ? error.message : "Something went wrong";
      setState({
        status: "error",
        progress: 0,
        scan: null,
        items: [],
        error: message,
        currentDish: null,
        dishProgress: null,
      });
      throw error;
    }
  }, []);

  const reset = useCallback(() => {
    if (abortRef.current) {
      abortRef.current.abort();
      abortRef.current = null;
    }
    setState({
      status: "idle",
      progress: 0,
      scan: null,
      items: [],
      error: null,
      currentDish: null,
      dishProgress: null,
    });
  }, []);

  return { ...state, startScan, reset };
}
