"use client";

import { useRef, useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";

interface CameraCaptureProps {
  onCapture: (file: File) => void;
  onClose: () => void;
}

export function CameraCapture({ onCapture, onClose }: CameraCaptureProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fallbackInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [ready, setReady] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [secureContext, setSecureContext] = useState(true);

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
  }, []);

  useEffect(() => {
    setSecureContext(window.isSecureContext);
  }, []);

  // getUserMedia path (secure context only)
  useEffect(() => {
    if (!secureContext) return;

    let mounted = true;

    async function start() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } },
          audio: false,
        });
        if (!mounted) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
          if (mounted) setReady(true);
        }
      } catch {
        if (mounted) setError("Camera access denied. Please allow camera permission and try again.");
      }
    }

    start();

    return () => {
      mounted = false;
      stopCamera();
    };
  }, [secureContext, stopCamera]);

  // Non-secure fallback: auto-click the hidden input to trigger native camera intent
  useEffect(() => {
    if (secureContext || error) return;
    // Small delay so the DOM is ready
    const t = setTimeout(() => fallbackInputRef.current?.click(), 200);
    return () => clearTimeout(t);
  }, [secureContext, error]);

  const handleFallbackFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onCapture(file);
    } else {
      onClose();
    }
  };

  const capture = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.drawImage(video, 0, 0);

    canvas.toBlob(
      (blob) => {
        if (!blob) return;
        const file = new File([blob], `menu-photo-${Date.now()}.jpg`, {
          type: "image/jpeg",
        });
        stopCamera();
        onCapture(file);
      },
      "image/jpeg",
      0.92
    );
  };

  const handleClose = () => {
    stopCamera();
    onClose();
  };

  // Error state (permission denied etc.)
  if (error) {
    return (
      <div className="fixed inset-0 z-50 bg-background flex flex-col items-center justify-center p-6 text-center gap-6">
        <div className="text-5xl">📷</div>
        <p className="text-muted-foreground max-w-sm">{error}</p>
        <Button variant="outline" onClick={handleClose}>
          Go Back
        </Button>
      </div>
    );
  }

  // Non-secure context: show a simple prompt + fallback input
  if (!secureContext) {
    return (
      <div className="fixed inset-0 z-50 bg-background flex flex-col items-center justify-center p-6 text-center gap-6">
        <input
          ref={fallbackInputRef}
          type="file"
          accept="image/*"
          capture="environment"
          onChange={handleFallbackFile}
          className="hidden"
        />
        <div className="text-5xl">📷</div>
        <div className="space-y-2">
          <p className="font-medium">Camera requires HTTPS</p>
          <p className="text-sm text-muted-foreground max-w-sm">
            Your browser blocks camera access on non-secure connections.
            Tap below to open your phone&apos;s camera directly.
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={handleClose}>
            Go Back
          </Button>
          <Button onClick={() => fallbackInputRef.current?.click()}>
            Open Camera
          </Button>
        </div>
      </div>
    );
  }

  // Secure context: fullscreen live camera
  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col">
      <video
        ref={videoRef}
        autoPlay
        playsInline
        muted
        className="flex-1 w-full object-cover"
      />
      <canvas ref={canvasRef} className="hidden" />
      <div className="flex items-center justify-center gap-8 py-6 bg-black">
        <Button
          variant="outline"
          size="lg"
          onClick={handleClose}
          className="rounded-full"
        >
          ✕
        </Button>
        <button
          onClick={capture}
          disabled={!ready}
          className="w-16 h-16 rounded-full bg-white border-4 border-white/60 active:scale-95 transition-transform disabled:opacity-50"
        />
        <div className="w-16" />
      </div>
    </div>
  );
}
