"use client";

import { Progress } from "@/components/ui/progress";
import { Card } from "@/components/ui/card";

interface ScanProgressProps {
  status: string;
  progress: number;
  currentDish?: string | null;
  dishProgress?: { done: number; total: number } | null;
}

const statusMessages: Record<string, string> = {
  idle: "Ready to scan",
  uploading: "Uploading image...",
  ai_reading: "AI is reading the menu...",
  processing: "Researching dishes...",
  completed: "Scan complete!",
  error: "Something went wrong",
};

export function ScanProgress({ status, progress, currentDish, dishProgress }: ScanProgressProps) {
  if (status === "idle") return null;

  return (
    <Card className="p-6">
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium">
            {statusMessages[status] || status}
          </span>
          {status !== "error" && (
            <span className="text-sm text-muted-foreground">
              {progress}%
            </span>
          )}
        </div>
        <Progress value={progress} className="h-2" />
        {status === "ai_reading" && (
          <p className="text-xs text-muted-foreground">
            Scanning the image with AI vision — this may take 30-60 seconds...
          </p>
        )}
        {status === "processing" && currentDish && (
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">
              Researching <span className="font-medium text-foreground">{currentDish}</span>
              {dishProgress && ` (${dishProgress.done} of ${dishProgress.total})`}...
            </p>
            {dishProgress && (
              <div className="flex gap-1.5 flex-wrap">
                {Array.from({ length: dishProgress.total }, (_, i) => (
                  <div
                    key={i}
                    className={`w-2 h-2 rounded-full ${
                      i < dishProgress.done
                        ? "bg-primary"
                        : "bg-muted-foreground/20"
                    }`}
                  />
                ))}
              </div>
            )}
          </div>
        )}
        {status === "processing" && !currentDish && (
          <p className="text-xs text-muted-foreground">
            Researching each dish with AI agents...
          </p>
        )}
      </div>
    </Card>
  );
}
