"use client";

import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { ImageUploader } from "@/components/scanner/ImageUploader";
import { ScanProgress } from "@/components/scanner/ScanProgress";
import { useScan } from "@/hooks/useScan";
import { cacheScanOffline } from "@/lib/offline-db";

export default function ScanPage() {
  const router = useRouter();
  const { status, progress, items, error, currentDish, dishProgress, startScan, reset } = useScan();

  const handleImageSelect = async (file: File) => {
    try {
      const result = await startScan(file);
      if (result?.scan?.id && result?.items?.length > 0) {
        // Cache full scan results locally (works even when MongoDB is unavailable)
        try {
          await cacheScanOffline({
            id: result.scan.id,
            status: result.scan.status || "completed",
            items_count: result.items.length,
            agent_summary: result.agent_summary || null,
            enriched: result.enriched || false,
            created_at: result.scan.created_at || new Date().toISOString(),
            items: result.items.map((item) => ({
              id: item.id,
              name: item.name,
              description: item.description,
              price: item.price,
              category: item.category,
              image_url: item.image_url || "",
              confidence: item.confidence,
            })),
          });
        } catch {
          // offline cache failure is non-critical
        }
        // Also store in sessionStorage for instant results page access
        try {
          sessionStorage.setItem(
            `scan-${result.scan.id}`,
            JSON.stringify({
              scan: result.scan,
              items: result.items,
              agent_summary: result.agent_summary,
              enriched: result.enriched,
              cached_at: Date.now(),
            })
          );
        } catch {
          // sessionStorage failure is non-critical
        }
        setTimeout(() => {
          router.push(`/results/${result.scan.id}`);
        }, 1000);
      }
    } catch {}
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <h1 className="text-2xl font-bold">MenuLens</h1>
          <Button variant="ghost" onClick={() => router.push("/")}>
            Home
          </Button>
        </div>
      </header>

      <main className="flex-1 container mx-auto px-4 py-8 max-w-2xl pb-24 md:pb-8">
        <div className="space-y-6">
          <div className="text-center">
            <h2 className="text-3xl font-bold">Scan a Menu</h2>
            <p className="text-muted-foreground mt-2">
              Upload a photo of any restaurant menu and AI will identify every dish
            </p>
          </div>

          {status === "completed" && items.length > 0 ? (
            <Card className="p-6 text-center space-y-4">
              <div className="text-5xl">✅</div>
              <h3 className="text-xl font-semibold">
                Found {items.length} dishes!
              </h3>
              <p className="text-muted-foreground">
                Redirecting to results...
              </p>
            </Card>
          ) : status === "error" ? (
            <Card className="p-6 text-center space-y-4">
              <div className="text-5xl">❌</div>
              <h3 className="text-xl font-semibold">Scan Failed</h3>
              <p className="text-muted-foreground">{error}</p>
              <Button onClick={reset}>Try Again</Button>
            </Card>
          ) : (
            <>
              <ImageUploader
                onImageSelect={handleImageSelect}
                disabled={status === "uploading" || status === "processing"}
              />
              <ScanProgress status={status} progress={progress} currentDish={currentDish} dishProgress={dishProgress} />
            </>
          )}
        </div>
      </main>
    </div>
  );
}
